module fixed_point_adder #(
    parameter Q = 15,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

wire [N-1:0] abs_a, abs_b;
wire [N-1:0] sum, diff;
wire [N-1:0] sign_a, sign_b;

assign sign_a = {N{a[N-1]}};
assign sign_b = {N{b[N-1]}};

assign abs_a = a ^ sign_a;
assign abs_b = b ^ sign_b;

assign {c[N-1], sum} = abs_a + abs_b;
assign {c[N-1], diff} = abs_a > abs_b ? abs_a - abs_b : abs_b - abs_a;

assign c = sign_a == sign_b ? sum : diff;

endmodule
